// === Tab: mySketch.js ===
p5.disableFriendlyErrors = true;
const SPEED = 0.6;
const FPS_COUNTER = true;
const f = 6;
const b = 5;
const samples = 3;
const gaussian = 0.2;
const multipler = 0.65;
const baseWeight = 0.22;

let curv = -0.03;
let dir = 1.0;
let distribution;
let weightoffset;
let sed;
let fc = 0;

const PI = Math.PI;
const HALF_PI = Math.PI / 2;
const cos = Math.cos;
const sin = Math.sin;
const pow = Math.pow;
const sqrt = Math.sqrt;
const atan2 = Math.atan2;

const MAX_STACK_SIZE = 10000; 
const STACK_STRIDE = 6; 
let stackData; 
let powCache = new Float32Array(b);

// ---- FPS SMOOTH ----
let smoothFPS = 0;
const fpsLerp = 0.07;
// --------------------

function setup() {
	frameRate(30);
	pixelDensity(1);
	sed = random() * 999999999;
	noiseDetail(2, 0.5);
	createCanvas(windowWidth, windowHeight);
	noFill();
	colorMode(RGB, 1);
	strokeCap(SQUARE);
	stackData = new Float64Array(MAX_STACK_SIZE * STACK_STRIDE);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function fractalIterative(startX, startY, startLx, startLy, startLayer, branch, startMutation, size) {

	let sp = 0; 

	stackData[sp++] = startX;
	stackData[sp++] = startY;
	stackData[sp++] = startLx;
	stackData[sp++] = startLy;
	stackData[sp++] = startLayer;
	stackData[sp++] = startMutation;

	const ctx = drawingContext;

	for (let i = 0; i < branch; i++) {
		powCache[i] = pow((i + 1) / branch, distribution);
	}

	const g = baseWeight;
	const widthPlusHeightDiv1000 = (width + height) / 1150;

	while (sp > 0) {

		let mutation = stackData[--sp];
		let layer = stackData[--sp];
		let ly = stackData[--sp];
		let lx = stackData[--sp];
		let y = stackData[--sp];
		let x = stackData[--sp];

		let mut = noise(mutation, fc / 253)*0.5 + 0.1;
		let lenMag = sqrt(lx * lx + ly * ly) * size * mut;
		let x2 = x + lx;
		let y2 = y + ly;

		let alpha = (baseWeight * layer) / f + baseWeight;
		let noiseComp = noise(mutation); 
		let sw = widthPlusHeightDiv1000 * ((layer + weightoffset) + noiseComp);

		if (sw > 0.1) {
			ctx.lineWidth = sw * 0.7 * mut * 2;
			ctx.strokeStyle = `rgba(0, ${Math.floor(g*255)}, 0, ${alpha})`;
			ctx.beginPath();
			ctx.moveTo(x, y);
			ctx.lineTo(x2, y2);
			ctx.stroke();
		}

		if (layer > 1) {
			let noiseVal = 1;
			let currentAngle = atan2(ly, lx);

			for (let i = branch - 1; i >= 0; i--) {

				let t = powCache[i];
				let newX = x + lx * t;
				let newY = y + ly * t;
				let newLenMag = lenMag * (multipler + noiseVal);

				let angleOffset = (i * PI + HALF_PI);
				angleOffset += (((((i+1)%2)*2)-1) * (curv - dir));
				angleOffset += (random() - 0.5 + random() - 0.5) * gaussian; 

				let totalAngle = currentAngle + angleOffset;
				let newLx = cos(totalAngle) * newLenMag;
				let newLy = sin(totalAngle) * newLenMag;
				let newMutation = mutation + random() * 2000;

				stackData[sp++] = newX;
				stackData[sp++] = newY;
				stackData[sp++] = newLx;
				stackData[sp++] = newLy;
				stackData[sp++] = layer - 1;
				stackData[sp++] = newMutation;
			}
		}
	}
}

let refresh = 0;

function draw() {

	randomSeed(sed);
	var ctx = drawingContext;

	ctx.fillStyle = "rgba(220, 220, 205, 0.33)";
	ctx.fillRect(0, 0, width, height);

	// ---- SMOOTH FPS ----
	if(FPS_COUNTER) {
		let currentFPS = 1000 / deltaTime;
		smoothFPS += (currentFPS - smoothFPS) * fpsLerp;

		fill(0.9);
		noStroke();
		rect(0, 0, 60, 30);
		fill(0);
		text(smoothFPS.toFixed(1), 10, 20);		
	}
	// ---------------------

	for(let i = 0; i < samples; i++) {

		fc = frameCount * SPEED + i*1000000 + refresh;
		distribution = pow(7, 2 * noise(fc / 552) - 0.8);
		weightoffset = noise(fc / 55) * 4 - 1;
		curv = (pow(noise(234 - fc / 783), 0.7)-0.5) + PI/3;
		dir = -PI - HALF_PI * pow(noise(0, fc / 1323 + 1000), 0.5)*1.4;
		let size = pow(noise(34234 - (fc / 1308)), 0.35)*0.6 + 0.5;
		push();
		translate(width / 2, height / 2);
		rotate(PI);
		translate(-width / 2, -height / 2);
		scale(0.3);
		translate(width * 0.5, height * 0.4);

		let shiftX = (noise(fc/100)-0.5) * 200;
		let shiftY = (noise(fc/100)-0.5) * 200;

		fractalIterative(
			width/samples*(((i)*3)-((samples-3)/3)) + shiftX,
			height*0.15 + shiftY,
			(width/(samples+1)) * (size*size) * 1.1,
			(height) * size * size * 1.1,
			f,
			b,
			0,
			size
		);

		pop();
	}
}

function keyPressed() {
	console.log(key);
  if (key === 'a') {

    refresh += 12345;
  }
}

